'use strict';

// MODULES //

var reinterpret = require( '@stdlib/strided/base/reinterpret-complex64' );
var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var max = require( '@stdlib/math/base/special/max' );
var min = require( '@stdlib/math/base/special/min' );


// MAIN //

/**
* Solves one of the systems of equations `A*x = b` or `A^T*x = b` or `x = A^H*x` where `b` and `x` are `N` element vectors and `A` is an `N` by `N` unit, or non-unit, upper or lower triangular band matrix, with ( `K` + 1 ) diagonals.
*
* @private
* @param {string} uplo - specifies whether `A` is an upper or lower triangular matrix
* @param {string} trans - specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param {string} diag - specifies whether `A` has a unit diagonal
* @param {NonNegativeInteger} N - number of elements along each dimension of `A`
* @param {NonNegativeInteger} K - number of super-diagonals or sub-diagonals of the matrix `A`
* @param {Complex64Array} A - input matrix
* @param {integer} strideA1 - stride of the first dimension of `A`
* @param {integer} strideA2 - stride of the second dimension of `A`
* @param {NonNegativeInteger} offsetA - starting index for `A`
* @param {Complex64Array} x - input vector
* @param {integer} strideX - stride length for `x`
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @returns {Complex64Array} `x`
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
*
* var A = new Complex64Array( [ 0.0, 0.0, 1.0, 1.0, 2.0, 2.0, 3.0, 3.0, 4.0, 4.0, 5.0, 5.0 ] );
* var x = new Complex64Array( [ 0.0, 2.0, 0.0, 16.0, 0.0, 46.0 ] );
*
* ctbsv( 'lower', 'no-transpose', 'non-unit', 3, 1, A, 2, 1, 0, x, 1, 0 );
* // x => <Complex64Array>[ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ]
*/
function ctbsv( uplo, trans, diag, N, K, A, strideA1, strideA2, offsetA, x, strideX, offsetX ) { // eslint-disable-line max-params, max-len
	var nonunit;
	var i0start;
	var i0end;
	var viewA;
	var viewX;
	var retmp;
	var imtmp;
	var magsq;
	var remul;
	var immul;
	var isrm;
	var sign;
	var rex;
	var imx;
	var rea;
	var ima;
	var ix0;
	var ix1;
	var sa0;
	var sa1;
	var oa2;
	var doa;
	var ox;
	var sx;
	var oa;
	var i0;
	var i1;
	var ia;

	// Note on variable naming convention: sa#, ix#, i# where # corresponds to the loop number, with `0` being the innermost loop...

	isrm = isRowMajor( [ strideA1, strideA2 ] );
	nonunit = ( diag === 'non-unit' );

	if ( isrm ) {
		// For row-major matrices, the last dimension has the fastest changing index...
		sa0 = strideA2 * 2; // stride increment for innermost loop
		sa1 = strideA1 * 2; // stride increment for outermost loop
	} else { // isColMajor
		// For column-major matrices, the first dimension has the fastest changing index...
		sa0 = strideA1 * 2; // stride increment for innermost loop
		sa1 = strideA2 * 2; // stride increment for outermost loop
	}
	// Reinterpret arrays as real-valued views of interleaved real and imaginary components:
	viewA = reinterpret( A, 0 );
	viewX = reinterpret( x, 0 );
	if ( trans === 'conjugate-transpose' ) {
		sign = -1;
	} else {
		sign = 1;
	}
	oa = offsetA * 2;
	ox = offsetX * 2;
	sx = strideX * 2;
	doa = sa1 - sa0;

	if (
		( !isrm && uplo === 'upper' && trans === 'no-transpose' ) ||
		( isrm && uplo === 'lower' && trans !== 'no-transpose' )
	) {
		ix1 = ox + ((N-1)*sx);
		oa2 = oa + ((N-1)*sa1) + (K*sa0);
		for ( i1 = N - 1; i1 >= 0; i1-- ) {
			rex = viewX[ ix1 ];
			imx = viewX[ ix1+1 ];
			retmp = rex;
			imtmp = imx;
			i0end = min(N-1, i1+K);
			ix0 = ix1 + sx;
			ia = oa2 + doa;
			for ( i0 = i1 + 1; i0 <= i0end; i0++ ) {
				rea = viewA[ ia ];
				ima = sign * viewA[ ia+1 ];
				rex = viewX[ ix0 ];
				imx = viewX[ ix0+1 ];
				retmp = f32(retmp - f32(f32(rea*rex) - f32(ima*imx)));
				imtmp = f32(imtmp - f32(f32(rea*imx) + f32(ima*rex)));
				ix0 += sx;
				ia += doa;
			}
			if ( nonunit ) {
				rea = viewA[ oa2 ];
				ima = sign * viewA[ oa2+1 ];
				magsq = f32(f32(rea*rea) + f32(ima*ima));
				remul = f32(f32(retmp*rea) + f32(imtmp*ima));
				immul = f32(f32(imtmp*rea) - f32(retmp*ima));
				retmp = f32(remul / magsq);
				imtmp = f32(immul / magsq);
			}
			viewX[ ix1 ] = retmp;
			viewX[ ix1+1 ] = imtmp;
			ix1 -= sx;
			oa2 -= sa1;
		}
		return x;
	}
	if (
		( !isrm && uplo === 'lower' && trans === 'no-transpose' ) ||
		( isrm && uplo === 'upper' && trans !== 'no-transpose' )
	) {
		ix1 = ox;
		oa2 = oa;
		for ( i1 = 0; i1 < N; i1++ ) {
			ix1 = ox + (i1*sx);
			rex = viewX[ ix1 ];
			imx = viewX[ ix1+1 ];
			retmp = rex;
			imtmp = imx;
			i0start = max(0, i1-K);
			ix0 = ox + (i0start*sx);
			ia = oa2 + ((i0start-i1)*doa);
			for ( i0 = i0start; i0 < i1; i0++ ) {
				rea = viewA[ ia ];
				ima = sign * viewA[ ia+1 ];
				rex = viewX[ ix0 ];
				imx = viewX[ ix0+1 ];
				retmp = f32(retmp - f32(f32(rea*rex) - f32(ima*imx)));
				imtmp = f32(imtmp - f32(f32(rea*imx) + f32(ima*rex)));
				ix0 += sx;
				ia += doa;
			}
			if ( nonunit ) {
				rea = viewA[ oa2 ];
				ima = sign * viewA[ oa2+1 ];
				magsq = f32(f32(rea*rea) + f32(ima*ima));
				remul = f32(f32(retmp*rea) + f32(imtmp*ima));
				immul = f32(f32(imtmp*rea) - f32(retmp*ima));
				retmp = f32(remul / magsq);
				imtmp = f32(immul / magsq);
			}
			viewX[ ix1 ] = retmp;
			viewX[ ix1+1 ] = imtmp;
			ix1 += sx;
			oa2 += sa1;
		}
		return x;
	}
	if (
		( !isrm && uplo === 'upper' && trans !== 'no-transpose' ) ||
		( isrm && uplo === 'lower' && trans === 'no-transpose' )
	) {
		ix1 = ox;
		oa2 = oa + (K*sa0);
		for ( i1 = 0; i1 < N; i1++ ) {
			ix1 = ox + (i1*sx);
			rex = viewX[ ix1 ];
			imx = viewX[ ix1+1 ];
			retmp = rex;
			imtmp = imx;
			i0start = max(0, i1-K);
			ix0 = ox + (i0start*sx);
			ia = oa2 + ( ( i0start - i1 ) * sa0 );
			for ( i0 = i0start; i0 < i1; i0++ ) {
				rea = viewA[ ia ];
				ima = sign * viewA[ ia+1 ];
				rex = viewX[ ix0 ];
				imx = viewX[ ix0+1 ];
				retmp = f32(retmp - f32(f32(rea*rex) - f32(ima*imx)));
				imtmp = f32(imtmp - f32(f32(rea*imx) + f32(ima*rex)));
				ix0 += sx;
				ia += sa0;
			}
			if ( nonunit ) {
				rea = viewA[ oa2 ];
				ima = sign * viewA[ oa2+1 ];
				magsq = f32(f32(rea*rea) + f32(ima*ima));
				remul = f32(f32(retmp*rea) + f32(imtmp*ima));
				immul = f32(f32(imtmp*rea) - f32(retmp*ima));
				retmp = f32(remul / magsq);
				imtmp = f32(immul / magsq);
			}
			viewX[ ix1 ] = retmp;
			viewX[ ix1+1 ] = imtmp;
			ix1 += sx;
			oa2 += sa1;
		}
		return x;
	}
	// ( !isrm && uplo === 'lower' && trans !== 'no-transpose' ) || ( isrm && uplo === 'upper' && trans === 'no-transpose' )
	ix1 = ox + ((N-1)*sx);
	oa2 = oa + ((N-1)*sa1);
	for ( i1 = N - 1; i1 >= 0; i1-- ) {
		rex = viewX[ ix1 ];
		imx = viewX[ ix1+1 ];
		retmp = rex;
		imtmp = imx;
		i0start = min(N-1, i1+K);
		ix0 = ox + (i0start*sx);
		ia = oa2 + ((i0start-i1)*sa0);
		for ( i0 = i0start; i0 > i1; i0-- ) {
			rea = viewA[ ia ];
			ima = sign * viewA[ ia+1 ];
			rex = viewX[ ix0 ];
			imx = viewX[ ix0+1 ];
			retmp = f32(retmp - f32(f32(rea*rex) - f32(ima*imx)));
			imtmp = f32(imtmp - f32(f32(rea*imx) + f32(ima*rex)));
			ix0 -= sx;
			ia -= sa0;
		}
		if ( nonunit ) {
			rea = viewA[ oa2 ];
			ima = sign * viewA[ oa2+1 ];
			magsq = f32(f32(rea*rea) + f32(ima*ima));
			remul = f32(f32(retmp*rea) + f32(imtmp*ima));
			immul = f32(f32(imtmp*rea) - f32(retmp*ima));
			retmp = f32(remul / magsq);
			imtmp = f32(immul / magsq);
		}
		viewX[ ix1 ] = retmp;
		viewX[ ix1+1 ] = imtmp;
		ix1 -= sx;
		oa2 -= sa1;
	}
	return x;
}


// EXPORTS //

module.exports = ctbsv;
